{
  "title": "Customary Law and Chemical-Weapons Reprisals",
  "setting": "Switzerland, 15 December 1988, Directorate for Public International Law of the Federal Department of Foreign Affairs.",
  "decider": "The Directorate for Public International Law of the Federal Department of Foreign Affairs",
  "agent_recast": false,
  "recast_note": "",
  "agent": "The Directorate for Public International Law of the Federal Department of Foreign Affairs",
  "agent_role": "decide",
  "situation": "The Directorate is assessing whether the prohibition on using chemical weapons has become customary international law. The 1925 Protocol prohibits the use of chemical weapons and extends its terms to bacteriological and biological weapons. Its wording has been read as confirming an existing rule, while earlier treaties and instruments also address poison or gas weapons. States have made different reservations to the Protocol, including reservations concerning reprisals after a party or its allies violate the prohibitions. Legal writers disagree about the effect of those reservations on the customary rule. The legal materials also raise questions about reprisals in kind, the rule’s application among belligerents, and the conditions governing reprisals.",
  "question": "What should the Directorate determine about customary law governing the first use of chemical weapons and their second use as reprisals?",
  "facts": [
    {
      "id": "F1",
      "kind": "authority",
      "status": "confirmed",
      "fact": "The 1925 Protocol prohibits the use in war of asphyxiating, poisonous or other gases and analogous substances or devices, and extends the prohibition to bacteriological and biological weapons.",
      "spans": [
        "src:12080fa976a6#p1.1"
      ]
    },
    {
      "id": "F2",
      "kind": "situation",
      "status": "assessed",
      "fact": "The Protocol’s wording has been understood by some legal writers as confirming, rather than creating, the prohibition on chemical weapons.",
      "spans": [
        "src:12080fa976a6#p1.1",
        "src:12080fa976a6#p1.2"
      ]
    },
    {
      "id": "F3",
      "kind": "authority",
      "status": "confirmed",
      "fact": "Earlier instruments address the prohibition of gases or poison, including the Treaty of Versailles, the Hague Regulations, the St Petersburg Declaration, the Oxford Manual, and the 1922 Washington treaty.",
      "spans": [
        "src:12080fa976a6#p1.2"
      ]
    },
    {
      "id": "F4",
      "kind": "situation",
      "status": "confirmed",
      "fact": "States’ reservations to the Protocol include both reservations limiting obligations to other parties and reservations concerning a response to violations by another state or its allies.",
      "spans": [
        "src:12080fa976a6#p1.3"
      ]
    },
    {
      "id": "F5",
      "kind": "situation",
      "status": "assessed",
      "fact": "Most legal writers regard the second type of reservation as expressing customary law, while Sandoz regards those reservations as irrelevant.",
      "spans": [
        "src:12080fa976a6#p1.5"
      ]
    },
    {
      "id": "F6",
      "kind": "authority",
      "status": "confirmed",
      "fact": "The legal materials state that reprisals must be of the same kind as the violation.",
      "spans": [
        "src:12080fa976a6#p1.3",
        "src:12080fa976a6#p1.4"
      ]
    },
    {
      "id": "F7",
      "kind": "authority",
      "status": "assessed",
      "fact": "The legal analysis considers the rule applicable when non-party states join a conflict and distinguishes the reprisal rights of parties that made reservations from those that did not.",
      "spans": [
        "src:12080fa976a6#p1.5",
        "src:12080fa976a6#p1.6"
      ]
    },
    {
      "id": "F8",
      "kind": "authority",
      "status": "confirmed",
      "fact": "Customary and treaty law impose subsidiarity, proportionality, and humanity conditions on reprisals.",
      "spans": [
        "src:12080fa976a6#p1.6"
      ]
    }
  ],
  "options": {
    "O1": {
      "do": "The Directorate should permit second use of chemical weapons only as reprisals in kind, subject to subsidiarity, proportionality, and humanity.",
      "move": "act",
      "disposition": "permit",
      "irreversible": false
    },
    "O2": {
      "do": "The Directorate should prohibit second use of chemical weapons even as reprisals in kind, under customary and treaty law.",
      "move": "act",
      "disposition": "prohibit",
      "irreversible": false
    }
  },
  "opposite_pair": [
    "O1",
    "O2"
  ],
  "real_option": "O1",
  "authored_options": [
    "O2"
  ],
  "no_opposite_reason": "",
  "provenance_note": "Translated from French by the extractor (R60)."
}
